INSERT INTO ratings(sid,year,centre,batch,role,person,subjects,r1,r2,r3,r4,r5,comment) VALUES
(1000547,2025,'Chembur Station','10th SSC','teacher','Ankush Sir','Marathi',4.0,5.0,5.0,5.0,5.0,'Ankush Sir is excellent for me Marathi. I am very weak Marathi and Ankush sir''s teaching helps me alot. I got my personal best marks Marathi this semester. He is great teaching.'),
(1000547,2025,'Chembur Station','10th SSC','teacher','Lata Mam','Hindi',3.0,4.0,5.0,5.0,5.0,'Lata mam is great. She is good at teaching hindi and I mostly understand her teaching.'),
(1000547,2025,'Chembur Station','10th SSC','teacher','Mahesh Sir','Algebra',5.0,5.0,5.0,5.0,5.0,'Mahesh sir is one of those who i respect greatly. His teaching is on next level. I understand every concept that he explains maths 1.'),
(1000547,2025,'Chembur Station','10th SSC','teacher','Vishal Sir','Geometry',2.0,3.0,4.0,4.0,4.0,'Vishal sir is okay. He is not that bad too. He explains some  very clearly.'),
(1000547,2025,'Chembur Station','10th SSC','teacher','Shubhankar Sir','Science 1',5.0,5.0,4.0,5.0,5.0,'He is the most respected my me. He is great at teaching science 1 and my marks science 1 has significantlycreased.'),
(1000547,2025,'Chembur Station','10th SSC','teacher','Vikas Sir','History',3.0,3.0,4.0,5.0,5.0,'I don''t like history so from my view Vikas sir is great! He makes history learning fun. He always gives us excellent examples.'),
(1000547,2025,'Chembur Station','10th SSC','teacher','Abhishek Sir','Geography',5.0,4.0,5.0,5.0,5.0,'Abhishek sir is so awesome! He makes me think geography is so much easy. He explains geography very excellent.'),
